# Alias for cache skip
SkipCache = SkipMemoization

def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    if isinstance(timeout, int):
        timeout = timedelta(seconds=timeout)

    if key_func is None:
        key_func = lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a

    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key_func(*args, **kwargs)
            try:
                if key in cache:
                    result, timestamp = cache[key]
                    if datetime.now() - timestamp < timeout:
                        return result
                    else:
                        del cache[key]
            except SkipCache:
                pass  # Bypass cache on skip

            result = func(*args, **kwargs)
            try:
                cache[key] = result, datetime.now()
            except SkipCache:
                pass  # Don't cache on skip
            return result

        def invalidate(*args, **kwargs):
            cache.pop(key_func(*args, **kwargs), None)
        wrapper.invalidate = invalidate

        def invalidate_all():
            cache.clear()
        wrapper.invalidate_all = invalidate_all

        wrapper.memory = cache
        return wrapper
    return decorator

